package com.starmaylight.arcana_industry.compat.jei;

import java.util.List;
import mezz.jei.api.gui.ingredient.IRecipeSlotsView;
import mezz.jei.api.recipe.category.IRecipeCategory;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;

/**
 * A multiblock JEI category that adds one "Structure" row below its background. Hovering the row shows
 * the complete formation conditions generated by {@link StructureConditions} from the packaged blueprint.
 * Implementations call {@link #drawStructure(GuiGraphics)} from their {@code draw} method.
 */
public interface StructureConditionsDisplay<T> extends IRecipeCategory<T> {
    int STRUCTURE_ROW_HEIGHT = 12;

    /** Controller block id whose packaged blueprint describes this category's structure, or null for none. */
    ResourceLocation structureController();

    default boolean hasStructureRow() { return StructureConditions.of(structureController()).isPresent(); }

    /** Top pixel of the structure row, directly below the category's own background. */
    default int structureRowY() { return getBackground().getHeight(); }

    @Override default int getHeight() { return structureRowY() + (hasStructureRow() ? STRUCTURE_ROW_HEIGHT : 0); }

    default Component structureSummary() {
        return StructureConditions.of(structureController()).map(layout -> (Component) Component.translatable(
            "jei.arcana_industry.structure.hint", layout.parts().size(), layout.materials().size())).orElse(Component.empty());
    }

    default void drawStructure(GuiGraphics graphics) {
        if (!hasStructureRow()) return;
        graphics.drawString(Minecraft.getInstance().font, structureSummary(), 0, structureRowY() + 2, 0x1F4F8F, false);
    }

    @Override default List<Component> getTooltipStrings(T recipe, IRecipeSlotsView slots, double mouseX, double mouseY) {
        if (mouseY < structureRowY() || mouseY >= getHeight() || mouseX < 0 || mouseX >= getWidth()) return List.of();
        return StructureConditions.of(structureController()).map(StructureConditions.Layout::tooltip).orElse(List.of());
    }
}
